import React, { useEffect, useState } from 'react';
import {
  Box, Card, CardContent, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Paper, IconButton,
  Button, Chip, Tooltip, Typography, TextField, InputAdornment, Skeleton,
} from '@mui/material';
import AddIcon    from '@mui/icons-material/Add';
import EditIcon   from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import SearchIcon from '@mui/icons-material/Search';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import api from '../../api/axios';
import PageHeader from '../../components/PageHeader';

const fmt = (v) =>
  v != null ? `₹ ${Math.abs(Number(v)).toLocaleString('en-IN', { minimumFractionDigits: 2 })}` : '—';

export default function CarExpenseList() {
  const [expenses, setExpenses] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [search,   setSearch]   = useState('');
  const navigate = useNavigate();

  const fetchAll = () => {
    setLoading(true);
    api.get('/car-expenses')
       .then(r => { setExpenses(r.data.data || []); setFiltered(r.data.data || []); })
       .catch(e => toast.error(e.message))
       .finally(() => setLoading(false));
  };

  useEffect(() => { fetchAll(); }, []);

  useEffect(() => {
    const q = search.toLowerCase();
    setFiltered(expenses.filter(e =>
      e.carNumberPlate?.toLowerCase().includes(q) ||
      e.purpose?.toLowerCase().includes(q) ||
      e.paidByName?.toLowerCase().includes(q)
    ));
  }, [search, expenses]);

  const handleDelete = (id) => {
    if (!window.confirm('Delete this expense?')) return;
    api.delete(`/car-expenses/${id}`)
       .then(() => { toast.success('Deleted'); fetchAll(); })
       .catch(e => toast.error(e.message));
  };

  return (
    <Box>
      <PageHeader
        title="Car Expenses"
        action={
          <Button variant="contained" startIcon={<AddIcon />}
                  onClick={() => navigate('/car-expenses/new')}>
            Add Expense
          </Button>
        }
      />

      <Card>
        <CardContent sx={{ pb: '16px !important' }}>
          <TextField
            placeholder="Search by plate, purpose or user..."
            value={search} onChange={e => setSearch(e.target.value)}
            size="small" sx={{ mb: 2, width: 320 }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon fontSize="small" color="action" />
                </InputAdornment>
              ),
            }}
          />

          <TableContainer component={Paper} elevation={0}
                          sx={{ border: '1px solid #e0e0e0', borderRadius: 2 }}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  {['#','Car','Purpose','Payment Mode','Type','Amount','Date','Paid By','Actions'].map(h => (
                    <TableCell key={h}>{h}</TableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  [...Array(5)].map((_, i) => (
                    <TableRow key={i}>
                      {[...Array(9)].map((_, j) => (
                        <TableCell key={j}><Skeleton /></TableCell>
                      ))}
                    </TableRow>
                  ))
                ) : filtered.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={9} align="center" sx={{ py: 5, color: 'text.secondary' }}>
                      No expenses found
                    </TableCell>
                  </TableRow>
                ) : filtered.map((e, idx) => {
                  const isCR = e.paymentType === 'CR';
                  return (
                    <TableRow key={e.id} hover>
                      <TableCell>{idx + 1}</TableCell>
                      <TableCell>
                        <Typography fontWeight={600} color="primary.main" fontSize="0.85rem">
                          {e.carNumberPlate}
                        </Typography>
                      </TableCell>
                      <TableCell>{e.purpose}</TableCell>
                      <TableCell>{e.paymentMode}</TableCell>
                      <TableCell>
                        <Chip
                          label={e.paymentType}
                          size="small"
                          sx={{
                            fontSize: '0.68rem', fontWeight: 700,
                            bgcolor: isCR ? '#e8f5e9' : '#ffebee',
                            color:   isCR ? '#1b5e20' : '#b71c1c',
                          }}
                        />
                      </TableCell>
                      <TableCell>
                        <Typography
                          fontSize="0.85rem" fontWeight={600}
                          color={isCR ? 'success.main' : 'error.main'}
                        >
                          {isCR ? '+' : '-'}{fmt(e.amount)}
                        </Typography>
                      </TableCell>
                      <TableCell>{e.expenseDate}</TableCell>
                      <TableCell>{e.paidByName}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                          <Tooltip title="Edit">
                            <IconButton size="small" color="primary"
                                        onClick={() => navigate(`/car-expenses/edit/${e.id}`)}>
                              <EditIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Delete">
                            <IconButton size="small" color="error"
                                        onClick={() => handleDelete(e.id)}>
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </TableContainer>

          <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
            Showing {filtered.length} of {expenses.length} records
          </Typography>
        </CardContent>
      </Card>
    </Box>
  );
}
